  "prediction_basis_card_ids": ["C193", "C177", "C195", "C165"],
  "claims": [
    {
      "claim": "The query is fosinoprilat, a dianionic phosphinic acid/carboxylic acid with neutral fraction 0, logD -0.6, TPSA 94.9, and no basic site; the calibrated physicochemical prior supports poor passive permeability and F below 20%.",
      "card_ids": []
    },
    {
      "claim": "C193 shows enalaprilat, the closest active-diacid ACE inhibitor analog, has human jejunal effective permeability of only 0.013 ± 0.009 ×10^-4 cm/s, an extremely low value supporting poor intestinal absorption for this compound class.",
      "card_ids": ["C193"]
    },
    {
      "claim": "C177 and C195 show enalaprilat permeability is not increased by net water absorption in human jejunum or by hypotonic perfusion in rat jejunum, indicating the absorption barrier is intrinsic and not overcome by paracellular enhancement.",
      "card_ids": ["C177", "C195"]
    },
    {
      "claim": "C165 shows DG013A, a phosphinic acid compound, has Caco-2 Papp below 1.0 ×10^-6 cm/s with no measurable efflux, supporting low passive permeability for the phosphinic acid motif and no efflux-mediated rescue.",
      "card_ids": ["C165"]
    },
    {
      "claim": "C213 and C235 show low hepatic intrinsic clearance for the related ACE inhibitor prodrugs enalapril and temocapril, indicating hepatic first-pass metabolism is unlikely to be the dominant barrier; this does not rescue the absorption-limited low F.",
      "card_ids": ["C213", "C235"]
    },
    {
      "claim": "C139 shows SQ-29852 has 60% human absorption despite low Caco-2 permeability, but that molecule contains a basic amino group and is a different phosphonate ACE inhibitor; it does not transfer to the query, which has no basic center.",
      "card_ids": ["C139"]
    },
    {
      "claim": "C205 shows PLGA nanoparticles raise enalaprilat ex vivo Papp to 4.61 ×10^-6 cm/s, but the query has no such formulation; this is a formulation caveat, not evidence of intrinsic high oral bioavailability.",
      "card_ids": ["C205"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C213", "C235"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability or matched oral/IV exposure data for fosinoprilat itself.",
    "No direct query permeability, efflux, or hepatic clearance measurement; L5/L6 records are for analog molecules.",
    "No data on possible active uptake transporters that could raise fosinoprilat absorption.",
    "No information on prodrug conversion or clinical formulation effects that could alter F.",
    "No direct fosinoprilat hepatic clearance or metabolic stability data; L6 only provides related ACE inhibitor prodrugs."
  ],
  "decision_summary": "Prediction remains low. L5 absorption evidence (enalaprilat extremely low jejunal permeability not enhanced by luminal conditions; phosphinic acid DG013A very low Caco-2 Papp without efflux) coherently supports an absorption-limited low F for the dianionic fosinoprilat-type query. L6 adds low hepatic intrinsic clearance for related ACE inhibitor prodrugs enalapril and temocapril, indicating hepatic first-pass metabolism is unlikely to be the dominant barrier; this does not overturn the absorption-based low prediction. Confidence stays moderate because direct fosinoprilat bioavailability data remain absent."
}

